To implement object pooling in Unity, you can create a generic pool class that manages a pool of objects. Here's a simple example of how you might set up a pool for a type of GameObject in C#:

```csharp
public class ObjectPool<T> where T : MonoBehaviour
{
    private List<T> pool;
    private GameObject prefab;
    private Transform parent;

    public ObjectPool(GameObject prefab, int size, Transform parent)
    {
        this.prefab = prefab;
        this.parent = parent;
        pool = new List<T>(size);

        for (int i = 0; i < size; i++)
        {
            T obj = Instantiate(prefab, parent).GetComponent<T>();
            obj.gameObject.SetActive(false);
            pool.Add(obj);
        }
    }

    public T Get()
    {
        foreach (T obj in pool)
        {
            if (!obj.gameObject.activeInHierarchy)
            {
                obj.gameObject.SetActive(true);
                return obj;
            }
        }
        return null; // Pool is exhausted
    }

    public void Return(T obj)
    {
        obj.gameObject.SetActive(false);
    }
}
```

This class allows you to preallocate a pool of objects and reuse them when needed, reducing the overhead of frequent object creation.

